"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { useModalState } from "hooks/useModalState";
import { useEffect, useRef, useState } from "react";
import { Lock } from "react-feather";
import { Flex, Text, styled as UiStyled, useIsDarkMode, useMedia, useSporeColors } from "ui/src";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { useAccount } from "hooks/useAccount";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { setSelectedLock, selectSelectedLock, selectPendingVotes } from "state/voting/slice";
import { useVotingStatus, VotingStatusUtils } from "hooks/useVotingStatus";
import { formatEther } from "viem";
const VoteBottomSlider = () => {
  const colors = useSporeColors();
  const dispatch = useAppDispatch();
  const selectedLock = useAppSelector(selectSelectedLock);
  const pendingVotes = useAppSelector(selectPendingVotes);
  const { toggleModal: toggleVotingModal } = useModalState(ModalName.Voting);
  const account = useAccount();
  const { data: userLocks } = useVeABXUserLocks(account.address);
  const locksCards = userLocks?.filter(
    (lock) => lock.owner.toLowerCase() === account.address?.toLowerCase()
  ) || [];
  const { lockStatuses, isLoading: votingStatusLoading } = useVotingStatus(locksCards);
  const selectedLockStatus = lockStatuses.find((status) => status.tokenId === selectedLock?.id);
  const selectedLockHasVoted = selectedLockStatus?.hasVoted || false;
  const canVote = selectedLock && pendingVotes.length > 0 && !selectedLockHasVoted;
  const isDarkMode = useIsDarkMode();
  const handleVote = () => {
    if (!selectedLock) {
      alert("Please select a veNFT lock from the slider below first.");
      return;
    }
    if (selectedLockHasVoted) {
      alert("This lock has already voted this epoch. Select a different lock or wait until Thursday when voting resets.");
      return;
    }
    if (pendingVotes.length === 0) {
      alert('Please select at least one gauge to vote on by clicking "Select" next to the gauges above.');
      return;
    }
    toggleVotingModal();
  };
  const votingStatusSummary = VotingStatusUtils.getVotingStatusSummary(lockStatuses);
  return <Flex
    row
    gap={"$spacing16"}
    $platform-web={{ position: "fixed", zIndex: 100 }}
    bottom={0}
    left={"50%"}
    transform={"translateX(-50%)"}
    hoverStyle={{ backgroundColor: isDarkMode ? "#2c2c2c" : "#e0e0e0" }}
    backdropFilter="blur(20px)"
    transition="all 0.2s ease-in-out"
    p={"$spacing16"}
    borderRadius={"$rounded16"}
    borderWidth={1}
    borderColor={"$surface3"}
    maxWidth={1200}
    width={"100%"}
    mx={"auto"}
    justifyContent="space-between"
    alignItems="center"
    $md={{ width: "calc(100% - 32px)", p: "$spacing12" }}
    position="relative"
  >
      <Flex
    position="absolute"
    borderRadius={"$rounded16"}
    inset={0}
    height={"100%"}
    width={"100%"}
    style={{
      background: isDarkMode ? `linear-gradient(180deg, #202020b2 0%, #2c2c2cb7 100%)` : `linear-gradient(180deg, #e0e0e0b4 0%, #dbdbdbb9 100%)`
    }}
  />
      <Slider lockStatuses={lockStatuses} votingStatusSummary={votingStatusSummary} />

      {
    /* Vote Summary */
  }
      <Flex flexDirection="column" gap="$gap4" minWidth={200} $md={{ display: "none" }}>
        {selectedLock && pendingVotes.length > 0 ? <>
            <Text variant="body4" color="$neutral2">
              Lock #{selectedLock.id} • {pendingVotes.length} pool{pendingVotes.length !== 1 ? "s" : ""}
            </Text>
            <Text variant="body3" color="$accent1">
              {formatEther(BigInt(selectedLock.votingPower)).slice(0, 8)} veABX ready
            </Text>
          </> : <>
            <Text variant="body4" color="$neutral2">
              {votingStatusSummary.unvoted} of {votingStatusSummary.total} locks available
            </Text>
            {votingStatusSummary.voted > 0 && <Text variant="body4" color="$statusCritical">
                {votingStatusSummary.voted} already voted this epoch
              </Text>}
          </>}
      </Flex>

      <Flex
    onPress={handleVote}
    cursor={canVote ? "pointer" : "not-allowed"}
    backgroundColor={canVote ? "$neutral1" : "$surface3"}
    color={canVote ? "$surface1" : "$neutral3"}
    opacity={canVote ? 1 : 0.6}
    padding="$spacing16"
    borderRadius="$rounded12"
    flex={1}
    justifyContent="center"
    alignItems="center"
    transition="all 0.2s ease-in-out"
    hoverStyle={{
      backgroundColor: canVote ? "$neutral1Hovered" : "$surface3"
    }}
    $md={{ display: "none" }}
  >
        <Text variant="buttonLabel2" color="inherit">
          {selectedLockHasVoted ? "Lock Already Voted" : selectedLock && pendingVotes.length > 0 ? `Vote (${pendingVotes.length} pool${pendingVotes.length !== 1 ? "s" : ""})` : "Vote"}
        </Text>
      </Flex>
    </Flex>;
};
export default VoteBottomSlider;
const SliderContainer = UiStyled(Flex, {
  overflow: "hidden",
  margin: "0 auto"
});
const NavButton = UiStyled(Flex, {
  alignItems: "center",
  justifyContent: "center",
  width: 30,
  height: "100%",
  borderRadius: "$rounded8",
  backgroundColor: "$surface1",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  cursor: "pointer",
  hoverStyle: {
    backgroundColor: "$surface1Hovered"
  }
});
const Slider = ({ lockStatuses, votingStatusSummary }) => {
  const media = useMedia();
  const account = useAccount();
  const dispatch = useAppDispatch();
  const selectedLock = useAppSelector(selectSelectedLock);
  const pendingVotes = useAppSelector(selectPendingVotes);
  const { data: userLocks, isLoading } = useVeABXUserLocks(account.address);
  const locksCards = userLocks?.filter(
    (lock) => lock.owner.toLowerCase() === account.address?.toLowerCase()
  ) || [];
  const [currentIndex, setCurrentIndex] = useState(0);
  const spaceBetween = media.md ? 0 : 10;
  const [cardWidth, setCardWidth] = useState(200);
  const cardsPerView = media.md ? 1 : 2;
  const maxIndex = Math.max(0, locksCards.length - cardsPerView);
  const sliderContainerRef = useRef(null);
  useEffect(() => {
    if (sliderContainerRef.current) {
      const newCardWidth = sliderContainerRef.current.offsetWidth / cardsPerView - spaceBetween / cardsPerView;
      setCardWidth(newCardWidth);
    }
  }, []);
  const handlePrev = () => {
    setCurrentIndex((prev) => Math.max(prev - 1, 0));
  };
  const handleNext = () => {
    setCurrentIndex((prev) => {
      let index = prev + 1;
      if (index > maxIndex) {
        index = 0;
      }
      return index;
    });
  };
  if (isLoading) {
    return <Flex row gap={"$spacing16"} flex={1} justifyContent="center" alignItems="center">
        <Text variant="body3" color="$neutral2">Loading locks...</Text>
      </Flex>;
  }
  if (locksCards.length === 0) {
    return <Flex row gap={"$spacing16"} flex={1} justifyContent="center" alignItems="center">
        <Text variant="body3" color="$neutral2">No locks available. Create a lock to start voting.</Text>
      </Flex>;
  }
  const allLocksVoted = votingStatusSummary.unvoted === 0 && votingStatusSummary.total > 0;
  if (allLocksVoted) {
    return <Flex row gap={"$spacing16"} flex={1} justifyContent="center" alignItems="center">
        <Text variant="body3" color="$neutral2">
          All {votingStatusSummary.total} lock{votingStatusSummary.total !== 1 ? "s have" : " has"} already voted this epoch. 
          Voting resets every Thursday.
        </Text>
      </Flex>;
  }
  return <Flex row gap={"$spacing16"} flex={1} justifyContent="flex-start" overflow="hidden">
      <Flex row gap="$spacing6" $md={{ display: "none" }}>
        <NavButton onPress={handlePrev} disabled={currentIndex === 0 || locksCards.length <= cardsPerView}>
          <Text>←</Text>
        </NavButton>
        <NavButton onPress={handleNext} disabled={currentIndex >= maxIndex || locksCards.length <= cardsPerView}>
          <Text>→</Text>
        </NavButton>
      </Flex>
      <Flex maxWidth={850} width={"100%"}>
        <SliderContainer ref={sliderContainerRef}>
          <Flex
    row
    transition="transform 0.5s ease-in-out"
    transform={`translateX(-${currentIndex * cardWidth + spaceBetween * currentIndex}px)`}
  >
            {locksCards.map((lock) => {
    const lockStatus = lockStatuses.find((status) => status.tokenId === lock.id);
    const hasVoted = lockStatus?.hasVoted || false;
    return <Slide
      key={lock.id}
      lock={lock}
      width={cardWidth}
      spaceBetween={spaceBetween}
      isSelected={selectedLock?.id === lock.id}
      selectedPools={pendingVotes.length}
      hasVoted={hasVoted}
      onSelect={() => {
        if (!hasVoted) {
          dispatch(setSelectedLock(lock));
        }
      }}
    />;
  })}
          </Flex>
        </SliderContainer>
      </Flex>
    </Flex>;
};
const Slide = ({ lock, width, spaceBetween, isSelected, selectedPools, hasVoted, onSelect }) => {
  const { toggleModal: toggleVortingModal } = useModalState(ModalName.Voting);
  const colors = useSporeColors();
  const formatAmount = (amount) => {
    const formatted = formatEther(BigInt(amount));
    const num = parseFloat(formatted);
    if (num < 1e3) return num.toFixed(2);
    if (num < 1e6) return (num / 1e3).toFixed(2) + "K";
    return (num / 1e6).toFixed(2) + "M";
  };
  const calculateLockDuration = () => {
    if (lock.permanent) return "Permanent";
    const now = Date.now() / 1e3;
    const lockEndSeconds = parseInt(lock.lockEnd);
    const daysRemaining = Math.max(0, Math.floor((lockEndSeconds - now) / (24 * 60 * 60)));
    if (daysRemaining < 30) return `${daysRemaining} days`;
    if (daysRemaining < 365) return `${Math.floor(daysRemaining / 30)} months`;
    return `${Math.floor(daysRemaining / 365)} years`;
  };
  const formatLockEndDate = () => {
    if (lock.permanent) return "Permanent Lock";
    return new Date(parseInt(lock.lockEnd) * 1e3).toLocaleString();
  };
  return <Flex
    py={"$spacing12"}
    px={"$spacing12"}
    backgroundColor={hasVoted ? "$surface2" : isSelected ? "$surface1Hovered" : "$surface1"}
    width={width}
    mr={spaceBetween}
    borderRadius={"$rounded16"}
    borderWidth={1}
    borderColor={hasVoted ? "$statusCritical" : isSelected ? "$accent1" : "$surface3Hovered"}
    cursor={hasVoted ? "not-allowed" : "pointer"}
    opacity={hasVoted ? 0.6 : 1}
    onPress={hasVoted ? void 0 : onSelect}
  >
      <Flex $lg={{ display: "none" }} row justifyContent="space-between" gap={"$gap16"}>
        <Flex className="left" row gap={"$gap12"} alignItems="center">
          <Flex
    borderRadius={"$rounded8"}
    backgroundColor={"$slate"}
    borderWidth={1}
    borderColor={"$surface2Hovered"}
    centered
    height={40}
    width={40}
  >
            <LogoProvider size={24} />
          </Flex>

          <Flex flexDirection="column" justifyContent="center" gap={"$gap8"}>
            <Flex row gap={"$gap12"} alignItems="center">
              <Text variant="body3">Lock #{lock.id}</Text> 
              <Lock size={14} color={colors.neutral3.val} />
              {lock.permanent && <Text variant="body4" color="$accent1">♾️</Text>}
              {hasVoted && <Flex
    backgroundColor="$statusCritical"
    borderRadius="$rounded4"
    px="$spacing4"
    py="$spacing2"
  >
                  <Text variant="body5" color="$surface1">VOTED</Text>
                </Flex>}
            </Flex>

            <MouseoverTooltip
    text={formatLockEndDate()}
    size={TooltipSize.Max}
    placement="top"
  >
              <Text variant="body4" color="$neutral3" cursor="pointer">
                {formatAmount(lock.amount)} ABX locked for {calculateLockDuration()}
              </Text>
            </MouseoverTooltip>
          </Flex>
        </Flex>

        <Flex flexDirection="column" gap={"$gap4"} alignItems="flex-end" justifyContent="flex-end">
          {selectedPools > 0 && <Text variant="body3" color="$accent1">
              {(selectedPools / 100 * 100).toFixed(1)}%
            </Text>}
          <Flex row gap={"$gap4"} alignItems="center">
            <Text
    variant="body4"
    backgroundColor={selectedPools > 0 ? "$greenVibrant" : "$surface2"}
    py={"$spacing4"}
    px={"$spacing8"}
    borderRadius={"$rounded8"}
    color={selectedPools > 0 ? "$surface1" : "$neutral2"}
  >
              {selectedPools}
            </Text>
            <Text variant="body4" color={selectedPools > 0 ? "$greenVibrant" : "$neutral2"}>
              Pool{selectedPools !== 1 ? "s" : ""} selected
            </Text>
          </Flex>
        </Flex>
      </Flex>

      <Flex
    row
    gap={"$gap12"}
    alignItems="flex-end"
    justifyContent="space-between"
    display="none"
    $lg={{ display: "flex" }}
    width={"100%"}
  >
        <Flex row gap={"$gap12"} alignItems="center" justifyContent="space-between">
          <LogoProvider size={24} />
          <Flex>
            <Text variant="body3">Lock #{lock.id}</Text>
            <Text variant="body4" color="$neutral3" mt={"$gap4"}>
              Voting Power: {formatAmount(lock.votingPower)} veABX
            </Text>
          </Flex>
        </Flex>

        <Flex row gap="$spacing8" alignItems="center">
          {hasVoted && <Flex
    backgroundColor="$statusCritical"
    borderRadius="$rounded4"
    px="$spacing4"
    py="$spacing2"
  >
              <Text variant="body5" color="$surface1">VOTED</Text>
            </Flex>}
          <Flex
    backgroundColor={selectedPools > 0 ? "$greenVibrant" : "$surface2"}
    borderRadius={"$roundedFull"}
    height={16}
    width={16}
    centered
    row
  >
            <Text variant="body4" color={selectedPools > 0 ? "$surface1" : "$neutral2"}>
              {selectedPools}
            </Text>
          </Flex>
        </Flex>
      </Flex>
    </Flex>;
};
